func checkInclusion(s1 string, s2 string) bool {
	if len(s1) > len(s2) {
		return false
	}
	s1Count := [26]int{}
	s2Count := [26]int{}
	for i := range s1 {
		s1Count[s1[i]-'a'] += 1
		s2Count[s2[i]-'a'] += 1
	}
	matches := 0
	for i := range s1Count {
		if s1Count[i] == s2Count[i] {
			matches += 1
		}
	}
	l := 0
	for i := len(s1); i < len(s2); i++ {
		if matches == 26 {
			return true
		}
		s2Count[s2[i]-'a'] += 1
		if s2Count[s2[i]-'a'] == s1Count[s2[i]-'a'] {
			matches += 1
		} else if s2Count[s2[i]-'a'] == s1Count[s2[i]-'a'] + 1 {
			matches -= 1
		}
		s2Count[s2[l]-'a'] -= 1
		if s2Count[s2[l]-'a'] == s1Count[s2[l]-'a'] {
			matches += 1
		} else if s2Count[s2[l]-'a'] == s1Count[s2[l]-'a'] - 1 {
			matches -= 1
		}
		l++
	}
	return matches == 26
}
